/**
 * Prevention and screening gaps of the November 2026 census (docs/proposals/gap-census-2026-11.md): cancer-preventing
 * vaccines, national HPV vaccination programmes, screening tests, national screening programmes and the oestrogen and
 * progesterone receptor immunohistochemistry kits.
 *
 * Sources, all read as raw files on 4 November 2026:
 * - Vaccines: the WHO list of prequalified vaccines (CSV export), the FDA Purple Book October 2026 data download and the
 *   EMA medicines output report. A date, a licence number or a status in a record below is the regulator's own field.
 * - HPV programmes: WHO's immunization data (WIISE), resources MT_AD_INTRO_LONG (introduction by year, antigens HPV and
 *   HepB_BD) and MT_AD_SCHEDULER (schedules), read through WHO's public xMart API. "Yes (P)" is WHO's "Yes (Partial)" and
 *   "Yes (R)" its "Yes (Risk groups)", from the legend of the WIISE page.
 * - Screening tests and the receptor kits: openFDA PMA, 510(k), De Novo and classification records, checked against the
 *   accessdata.fda.gov page where the openFDA record was silent (a withdrawal date, a De Novo classification name).
 * - Screening programmes: the IARC CanScreen5 country fact sheets (the markdown each fact sheet is built from), and
 *   Europe PMC abstracts for three programmes outside CanScreen5's three sites.
 *
 * The country programme rows were generated from the WHO and IARC files by a script that copies each field into a
 * sentence; quoted notes are the country's own words in WHO's table. Performance figures from CanScreen5 were left out
 * because the fact sheets spread them across age-group columns that the markdown does not label; each record links
 * the fact sheet, which shows them.
 *
 * The oestrogen and progesterone receptor kits name the readouts they measure in their own `related` (the rule in
 * src/data/readout-test-records.ts); the readouts' `drugs` fields are untouched.
 */
import type { CollectionInput, DrugInput, EntityInput, TermInput } from "@/lib/schema";

const asOf = "2026-11-04";
const PMA = (n: string) => ({ label: `FDA PMA ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpma/pma.cfm?id=${n}` });
const DENOVO = (n: string) => ({ label: `FDA De Novo ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/denovo.cfm?id=${n}` });
const K510 = (n: string) => ({ label: `FDA 510(k) ${n}`, url: `https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=${n}` });
const DOI = (label: string, doi: string) => ({ label, url: `https://doi.org/${doi}` });
const EPAR = (name: string, slug: string) => ({ label: `EMA: ${name} (EPAR)`, url: `https://www.ema.europa.eu/en/medicines/human/EPAR/${slug}` });
const WHO_PQ = { label: "WHO list of prequalified vaccines (CSV export)", url: "https://extranet.who.int/prequal/vaccines/prequalified/export?page&_format=csv" };
const PURPLE_BOOK = { label: "FDA Purple Book, October 2026 data download", url: "https://www.accessdata.fda.gov/drugsatfda_docs/PurpleBook/2026/purplebook-search-October-data-download.csv" };
const WHO_HEPB = { label: "WHO fact sheet: hepatitis B (28 July 2026)", url: "https://www.who.int/news-room/fact-sheets/detail/hepatitis-b" };

/** WHO's hepatitis B fact sheet of 28 July 2026, in its own figures; shared by every hepatitis B vaccine record. */
const HEPB_WHY = "Why it is a cancer vaccine: WHO estimates that hepatitis B caused 1.1 million deaths in 2024, mostly from cirrhosis and hepatocellular carcinoma (primary liver cancer), and that infection in infancy and early childhood becomes chronic in about 95% of cases. WHO recommends that all babies receive the vaccine as soon as possible after birth (within 24 hours), followed by two or three further doses (WHO fact sheet, 28 July 2026).";

const vax = (x: Omit<DrugInput, "kind" | "asOf" | "modality" | "mechanism"> & { modality?: string; mechanism?: string }): DrugInput => ({
  kind: "drug", asOf, modality: "Prophylactic vaccine (recombinant)", sections: ["prevention"],
  mechanism: "A recombinant viral surface protein, given by injection, trains the immune system to make antibodies that block infection by the virus.",
  ...x, tags: ["preventive-vaccine", ...(x.tags ?? [])],
});
const hepb = (x: Omit<DrugInput, "kind" | "asOf" | "modality" | "mechanism"> & { modality?: string }): DrugInput => vax({
  mechanism: "Recombinant hepatitis B surface antigen (the active substance the regulators name) trains the immune system to make antibodies against hepatitis B virus, preventing the infection that can lead to liver cancer.",
  ...x, technologies: ["hpv-vaccine", ...(x.technologies ?? [])], terms: ["hbv-hcv", ...(x.terms ?? [])],
  links: [...(x.links ?? []), WHO_HEPB], tags: ["hepatitis-b-vaccine", ...(x.tags ?? [])],
});
const hpv = (x: Omit<DrugInput, "kind" | "asOf" | "modality" | "mechanism"> & { modality?: string }): DrugInput => vax({
  modality: "Prophylactic vaccine (virus-like particles)",
  mechanism: "Recombinant HPV L1 capsid proteins form virus-like particles that train the immune system to make antibodies against the HPV types the vaccine covers.",
  ...x, technologies: ["hpv-vaccine", ...(x.technologies ?? [])], terms: x.terms ?? [], pathways: ["oncogenic-viruses", ...(x.pathways ?? [])], tags: ["hpv-vaccine", ...(x.tags ?? [])],
});
const test = (x: Omit<DrugInput, "kind" | "asOf">): DrugInput => ({ kind: "drug", asOf, sections: ["early-detection", "diagnostics"], ...x, tags: ["test", "screening-test", ...(x.tags ?? [])] });
const ihc = (x: Omit<DrugInput, "kind" | "asOf" | "modality" | "mechanism">): DrugInput => ({
  kind: "drug", asOf, sections: ["diagnostics"], modality: "Immunohistochemistry assay (oestrogen and progesterone receptor protein, breast tumour tissue)",
  mechanism: "An antibody that binds the receptor protein is applied to a thin slice of the tumour; a chemical stain makes the cells carrying the receptor visible, and a pathologist reports the share of tumour cells that stain and how strongly.",
  ...x, tags: ["test", "ihc-assay", ...(x.tags ?? [])],
});
const prog = (x: Omit<TermInput, "kind" | "asOf" | "category">): TermInput => ({
  kind: "term", asOf, category: "Epidemiology & prevention", sections: ["prevention"], cancers: ["cervical"], technologies: ["hpv-vaccine"], pathways: ["oncogenic-viruses"], ...x, tags: ["vaccination-programme", ...(x.tags ?? [])],
});
const screen = (x: Omit<TermInput, "kind" | "asOf" | "category">): TermInput => ({
  kind: "term", asOf, category: "Epidemiology & prevention", sections: ["early-detection"], terms: ["screening"], ...x, tags: ["screening-programme", ...(x.tags ?? [])],
});

