    regulatoryEvents: [{ date: "2003-03-31", type: "approval", region: "US", note: "hc2 High-Risk HPV DNA Test approved for adjunctive screening with Pap in women 30 and older (P890064/S009)", source: "https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpma/pma.cfm?id=P890064" }],
    cancers: ["cervical"], companies: ["qiagen"], technologies: ["hpv-testing"], terms: ["cin-hsil", "screening"], related: ["cobas-hpv", "aptima-hpv"],
