// ======================================================================== the sources, as collections
// Each source this round read is a collection record that names the records drawn from it, and each record names its
// source back, so a reader can go from a vaccine to the WHO list and from the list to every vaccine on it.
const ids = (xs: EntityInput[]) => xs.map((x) => x.id);
const PQ_IDS = ["engerix-b", "euvax-b", "bevac", "sii-hepatitis-b-vaccine", "heberbiovac-hb", "cecolin", "walrinvax"];
const CS5_IDS = ids(screeningProgrammes2026_11).filter((id) => /^screening-[a-z]{3}-/.test(id));
const OTHER_SCREENING_IDS = ids(screeningProgrammes2026_11).filter((id) => !CS5_IDS.includes(id));
const coll = (x: Omit<CollectionInput, "kind" | "asOf">): CollectionInput => ({ kind: "collection", asOf, ...x });

