/** A record names the source collection it was drawn from, so every collection has its records and every record its source. */
const from = <T extends EntityInput>(xs: T[], source: string, only?: string[]): T[] =>
  xs.map((x) => (only && !only.includes(x.id) ? x : { ...x, related: [...(x.related ?? []), source] }));

